import{c as a,$ as r,Q as s,j as o,g as e,o as n,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const b=JSON.parse('{"title":"Общая информация о пространствах","description":"Архитектура изолированных рабочих пространств в ОмниКрафт ЕРП, отраслевые профили производства и сервиса, правила вводного инструктажа и управление архивом.","frontmatter":{"title":"Общая информация о пространствах","description":"Архитектура изолированных рабочих пространств в ОмниКрафт ЕРП, отраслевые профили производства и сервиса, правила вводного инструктажа и управление архивом.","datePublished":"2026-11-14","dateModified":"2026-11-25","order":5},"headers":[],"relativePath":"ru/docs/spaces/general.md","filePath":"ru/docs/spaces/general.md","lastUpdated":1795564800000}'),g={name:"ru/docs/spaces/general.md"},h={id:"общая-информация-о-пространствах",tabindex:"-1"};function c(f,t,p,u,x,y){const l=r("DocIcon");return s(),o("div",null,[e("h1",h,[n(l,{name:"layers"}),t[0]||(t[0]=i(" Общая информация о пространствах ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#общая-информация-о-пространствах","aria-label":'Permalink to "Общая информация о пространствах"'},"​",-1))]),t[2]||(t[2]=d('<p>В основе архитектуры <strong>ОмниКрафт ЕРП</strong> заложен принцип строгой изоляции рабочих пространств. Опытный ремесленник, мастер или руководитель мастерской редко ограничивается одним узким ремеслом: столярное дело часто соседствует с реставрацией, кожевенное производство — с индивидуальным сервисом, а коммерческая мастерская — с личными проектами.</p><p>Попытка вести столь разнородную деятельность в рамках единой учетной книги неизбежно приводит к искажению себестоимости, путанице на складе сырья и неразберихе в кассе. В системе каждое направление живет собственной экономической жизнью, сохраняя абсолютную чистоту баланса.</p><hr><h2 id="архитектурная-модель-изоляции-изоляция-баз-данных" tabindex="-1">Архитектурная модель изоляции (изоляция баз данных) <a class="header-anchor" href="#архитектурная-модель-изоляции-изоляция-баз-данных" aria-label="Permalink to &quot;Архитектурная модель изоляции (изоляция баз данных)&quot;">​</a></h2><p>Каждое рабочее пространство в <strong>ОмниКрафт ЕРП</strong> представляет собой полностью автономный цифровой цех со своей базой данных SQLite:</p><ul><li><strong>Физическая изоляция файлов:</strong> База данных каждого пространства хранится в персональном файле каталога программы. Любые операции, архивация или перенастройка нормативов в одной мастерской физически изолированы от соседних направлений.</li><li><strong>Независимая себестоимость:</strong> В каждом пространстве действуют собственные нормативы — часовая ставка мастера, торговая наценка и статьи накладных расходов.</li><li><strong>Изолированный склад и касса:</strong> Остатки сырья, производственные станки, кассовые ордера и взаиморасчеты ведутся строго внутри своего контура, не смешивая производственные закупки с сервисными деталями.</li><li><strong>Автономность без внешних серверов:</strong> Все базы данных хранятся исключительно на вашем компьютере. Программа не отправляет производственные секреты на сторонние серверы и не зависит от наличия подключения к интернету.</li></ul><div class="info custom-block"><p class="custom-block-title">Защита финансовой отчетности</p><p>Разделение направлений по независимым пространствам защищает от ложного ощущения прибыльности: всегда точно видно, какое направление генерирует чистую прибыль, а какое требует пересмотра расценок или оптимизации технологических карт.</p></div><hr><h2 id="первыи-запуск-вводныи-инструктаж" tabindex="-1">Первый запуск: Вводный инструктаж <a class="header-anchor" href="#первыи-запуск-вводныи-инструктаж" aria-label="Permalink to &quot;Первый запуск: Вводный инструктаж&quot;">​</a></h2><p>При первом запуске чистой программы открывается окно вводного инструктажа, где предлагается выбрать стартовый профиль мастерской:</p><ol><li><strong>Выбор ведущего направления:</strong> Определяется базовая модель — <strong>«Производство и ремесло»</strong> либо <strong>«Услуги и сервисный центр»</strong>. Программа мгновенно настраивает состав рабочих вкладок и терминологию под выбранную специфику.</li><li><strong>Ознакомительный демонстрационный режим:</strong> В нижней части экрана доступна кнопка <strong>«Попробовать на живом примере»</strong>. При нажатии система наполнит пространство наглядными демонстрационными данными (типовые материалы, рецепты изделий, станки и пробные операции). Это позволяет сразу изучить логику программы без ручного заведения номенклатуры с нуля.</li></ol><div class="tip custom-block"><p class="custom-block-title">Безопасный тест-драйв</p><p>Демонстрационные данные служат интерактивным учебником. Можно свободно запускать пробные партии на верстаке, оформлять продажи и списывать сырье. Когда всё готово к учету реального дела, достаточно создать чистое пространство или очистить базу напрямую из настроек.</p></div><hr><h2 id="деиствующие-отраслевые-профили" tabindex="-1">Действующие отраслевые профили <a class="header-anchor" href="#деиствующие-отраслевые-профили" aria-label="Permalink to &quot;Действующие отраслевые профили&quot;">​</a></h2><p>В текущей версии <strong>ОмниКрафт ЕРП</strong> реализованы два ключевых отраслевых контура:</p><h3 id="_1-профиль-«производство-и-ремесло»" tabindex="-1">1. Профиль «Производство и ремесло» <a class="header-anchor" href="#_1-профиль-«производство-и-ремесло»" aria-label="Permalink to &quot;1. Профиль «Производство и ремесло»&quot;">​</a></h3><p>Шаблон спроектирован для классического материального производства, где закупленное сырье проходит стадии обработки, раскроя и сборки:</p><ul><li><strong>Склад сырья и материалов:</strong> Поступление и списание материалов с автоматическим расчетом себестоимости методом скользящей средней стоимости (МАК).</li><li><strong>Калькулятор технологических карт:</strong> Расчет расхода материалов, времени мастера и накладных расходов на единицу продукции с определением минимального порога безубыточности.</li><li><strong>Производственный верстак:</strong> Учет партий в работе, резервирование сырья и выпуск готовой продукции.</li><li><strong>Склад готовых товаров и продажи:</strong> Учет готовых изделий и их реализация со списанием партий методом первых партий (ФИФО).</li></ul><h3 id="_2-профиль-«услуги-и-сервисныи-центр»" tabindex="-1">2. Профиль «Услуги и сервисный центр» <a class="header-anchor" href="#_2-профиль-«услуги-и-сервисныи-центр»" aria-label="Permalink to &quot;2. Профиль «Услуги и сервисный центр»&quot;">​</a></h3><p>Шаблон предназначен для сервисных мастерских, индивидуального пошива, ремонта техники, реставрации и проектных работ:</p><ul><li><strong>Каталог услуг:</strong> Прейскурант с поддержкой фиксированных цен за операцию, расценок по нормо-часам и составных смет.</li><li><strong>Рабочий стол заказ-нарядов:</strong> Контроль стадий выполнения заказов, списание использованных запчастей и расходников, фиксация предоплат и расчет остатка к доплате.</li><li><strong>Клиентская база:</strong> Реестр заказчиков с контактами и полной историей выполненных работ. При этом разовый заказ можно оформить за секунды без обязательной регистрации контрагента.</li><li><strong>Интеграция с кассой:</strong> При закрытии заказ-наряда итоговая оплата автоматически попадает в кассу (ДДС), исключая ручной повторный ввод.</li></ul><details class="details custom-block"><summary>Архитектурный задел диалога создания</summary><p>В окне добавления пространств также представлены карточки перспективных отраслевых шаблонов («Торговля / Ритейл», «Обучение / Цифровые товары», «Деятельность / Хобби»). Они отмечены значком замка и заложены в модульную архитектуру ядра для будущих обновлений программы.</p></details><hr><h2 id="управление-через-боковую-панель-шторку" tabindex="-1">Управление через боковую панель (Шторку) <a class="header-anchor" href="#управление-через-боковую-панель-шторку" aria-label="Permalink to &quot;Управление через боковую панель (Шторку)&quot;">​</a></h2><p>Все операции с пространствами сосредоточены в компактной боковой панели, которая выдвигается по нажатию кнопки с символом мастерской (<code>⛯</code>) в верхней строке приложения или по сочетанию клавиш <code>Ctrl+Shift+W</code>:</p><ul><li><strong>Паспорт мастерской:</strong> Каждому пространству присваивается понятное пользовательское название (<em>«Кожевенный цех»</em>, <em>«Ремонт оптики»</em>) и подробное описание (адрес помещения, график или перечень направлений).</li><li><strong>Информативный предпросмотр:</strong> В карточке пространства выводятся две строки описания с аккуратным многоточием. Интерфейс остается чистым и не перегружен всплывающими подсказками.</li><li><strong>Редактирование параметров:</strong> Нажатие на значок карандаша открывает окно, где можно просмотреть полный текст описания и скорректировать реквизиты.</li><li><strong>Быстрое переключение:</strong> Клик по строке нужного пространства мгновенно переключает рабочий экран на выбранную мастерскую.</li></ul><hr><h2 id="жизненныи-цикл-пространства-и-тарифные-правила" tabindex="-1">Жизненный цикл пространства и тарифные правила <a class="header-anchor" href="#жизненныи-цикл-пространства-и-тарифные-правила" aria-label="Permalink to &quot;Жизненный цикл пространства и тарифные правила&quot;">​</a></h2><p>Управление пространствами подчинено четким правилам, исключающим потерю производственной информации:</p><h3 id="правило-одного-активного-пространства-тарифы-бесплатныи-и-стандарт" tabindex="-1">Правило одного активного пространства (Тарифы Бесплатный и Стандарт) <a class="header-anchor" href="#правило-одного-активного-пространства-тарифы-бесплатныи-и-стандарт" aria-label="Permalink to &quot;Правило одного активного пространства (Тарифы Бесплатный и Стандарт)&quot;">​</a></h3><ul><li><strong>Концентрация на одном деле:</strong> В базовых лицензиях активно ровно одно рабочее пространство. Ведется либо производство, либо сервисный центр.</li><li><strong>Свободная смена профиля через архив:</strong> Если решено перепрофилировать мастерскую или открыть другое направление, текущее пространство в любой момент отправляется в архив через боковую панель. Слот освобождается, и можно создать новое пространство.</li></ul><h3 id="льготныи-период-безопаснои-отмены-архивации" tabindex="-1">Льготный период безопасной отмены архивации <a class="header-anchor" href="#льготныи-период-безопаснои-отмены-архивации" aria-label="Permalink to &quot;Льготный период безопасной отмены архивации&quot;">​</a></h3><ul><li><strong>Защита от случайных действий:</strong> При отправке пространства в архив в боковой панели запускается 60-минутный таймер безопасной отмены.</li><li><strong>Мгновенное восстановление:</strong> В течение 60 минут вернуть пространство из архива в рабочий статус можно бесплатно и мгновенно.</li><li><strong>Правило по истечении 60 минут:</strong> Спустя час для разархивирования потребуется лицензия ПРО. Этот регламент защищает систему от недобросовестного поочередного ведения нескольких параллельных бизнесов на базовом тарифе.</li></ul><h3 id="мультипространства-в-тарифе-про" tabindex="-1">Мультипространства в тарифе ПРО <a class="header-anchor" href="#мультипространства-в-тарифе-про" aria-label="Permalink to &quot;Мультипространства в тарифе ПРО&quot;">​</a></h3><p>Лицензия ПРО снимает любые количественные ограничения:</p><ul><li><strong>Неограниченное число активных пространств:</strong> Можно одновременно вести десятки мастерских, студий и филиалов.</li><li><strong>Мгновенное переключение:</strong> Переход между проектами происходит за секунду без отправки баз в архив.</li><li><strong>Неограниченное разархивирование:</strong> Любое архивное пространство возвращается в работу в любой момент времени.</li></ul><h3 id="принцип-свободы-данных" tabindex="-1">Принцип свободы данных <a class="header-anchor" href="#принцип-свободы-данных" aria-label="Permalink to &quot;Принцип свободы данных&quot;">​</a></h3><p>ОмниКрафт ЕРП не удерживает данные мастера. Даже если пространство находится в архиве, всегда доступно бесплатное скачивание резервных копий базы данных и выгрузка информации в электронные таблицы.</p><hr><h2 id="сводная-матрица-возможностеи-управления-пространствами" tabindex="-1">Сводная матрица возможностей управления пространствами <a class="header-anchor" href="#сводная-матрица-возможностеи-управления-пространствами" aria-label="Permalink to &quot;Сводная матрица возможностей управления пространствами&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Возможность системы</th><th style="text-align:left;">Тариф «Бесплатный»</th><th style="text-align:left;">Тариф «Стандарт»</th><th style="text-align:left;">Тариф «ПРО»</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Число одновременно активных пространств</strong></td><td style="text-align:left;">1 пространство</td><td style="text-align:left;">1 пространство</td><td style="text-align:left;">Без ограничений</td></tr><tr><td style="text-align:left;"><strong>Отраслевые профили (Производство / Сервис)</strong></td><td style="text-align:left;">Доступны все</td><td style="text-align:left;">Доступны все</td><td style="text-align:left;">Доступны все</td></tr><tr><td style="text-align:left;"><strong>Ознакомительный демонстрационный режим</strong></td><td style="text-align:left;">Включен</td><td style="text-align:left;">Включен</td><td style="text-align:left;">Включен</td></tr><tr><td style="text-align:left;"><strong>Отправка пространств в архив</strong></td><td style="text-align:left;">Без ограничений</td><td style="text-align:left;">Без ограничений</td><td style="text-align:left;">Без ограничений</td></tr><tr><td style="text-align:left;"><strong>Бесплатный возврат из архива (до 60 минут)</strong></td><td style="text-align:left;">Да (мгновенно)</td><td style="text-align:left;">Да (мгновенно)</td><td style="text-align:left;">Да (мгновенно)</td></tr><tr><td style="text-align:left;"><strong>Разархивирование спустя 60 минут</strong></td><td style="text-align:left;">Требуется ПРО</td><td style="text-align:left;">Требуется ПРО</td><td style="text-align:left;">Без ограничений</td></tr><tr><td style="text-align:left;"><strong>Параллельное ведение нескольких бизнесов</strong></td><td style="text-align:left;">Нет (поочередно)</td><td style="text-align:left;">Нет (поочередно)</td><td style="text-align:left;">Да (полноценный мульти-режим)</td></tr><tr><td style="text-align:left;"><strong>Выгрузка резервных копий из архива</strong></td><td style="text-align:left;">Бесплатно всегда</td><td style="text-align:left;">Бесплатно всегда</td><td style="text-align:left;">Бесплатно всегда</td></tr></tbody></table><hr><h2 id="консолидация-капитала-связь-со-сквозным-контуром" tabindex="-1">Консолидация капитала: Связь со сквозным контуром <a class="header-anchor" href="#консолидация-капитала-связь-со-сквозным-контуром" aria-label="Permalink to &quot;Консолидация капитала: Связь со сквозным контуром&quot;">​</a></h2><p>Разделение мастерских на независимые пространства не разрывает общую картину совокупного капитала.</p><p>На верхнем уровне системы работает модуль <strong>«Мой капитал»</strong>. Он автоматически опрашивает базы данных всех мастерских, собирает стоимость оборудования на балансе, остатки материалов на складах, оценку готовых изделий на витринах и деньги в кассах.</p><p>В результате формируется единый консолидированный баланс и расчет чистых активов, не тратя время на ручное сведение таблиц. Подробнее принципы работы сквозного контура описаны в разделе <a href="/ru/docs/resources/capital">«Капитал»</a>.</p>',46))])}const q=a(g,[["render",c]]);export{b as __pageData,q as default};
